def count_multiples_of_4(n):
    """Count the number of subsets of {1, ..., n} that contain at least one multiple of 4."""
    count = 0
    for r in range(1, n + 1):
        for s in combinations(range(1, r + 1), r):
            if any(x % 4 == 0 for x in s):
                count += 1
    return count

